  (forall j, In j [3; 4; 27]%nat -> getr R7 (reg j) = getr Ri (reg j)) ->
  (forall j, In j [1; 8; 9; 18; 19; 20; 21; 22; 23; 24; 25; 26]%nat -> getr R7 (reg j) = getr R (reg j)) ->
